package org.apache.commons.math.util;

import java.io.*;
import java.math.*;
import java.math.BigDecimal;
import java.util.*;
import java.util.Arrays;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;

public class MathUtils_binomialCoefficient_TriageGen2Test {

    @Test
    public void testBinomialCoefficient_BaseCases() {
        // (n == k) || (k == 0) returns 1
        assertEquals(1L, MathUtils.binomialCoefficient(5, 5));
        assertEquals(1L, MathUtils.binomialCoefficient(5, 0));
        assertEquals(1L, MathUtils.binomialCoefficient(0, 0));
    }

    @Test
    public void testBinomialCoefficient_LinearCases() {
        // (k == 1) || (k == n - 1) returns n
        assertEquals(5L, MathUtils.binomialCoefficient(5, 1));
        assertEquals(5L, MathUtils.binomialCoefficient(5, 4));
        assertEquals(1L, MathUtils.binomialCoefficient(1, 0)); // k=0 case handled above, but k=1, n-1=0
    }

    @Test
    public void testBinomialCoefficient_StandardValues() {
        // General cases
        assertEquals(10L, MathUtils.binomialCoefficient(5, 2));
        assertEquals(10L, MathUtils.binomialCoefficient(5, 3));
        assertEquals(20L, MathUtils.binomialCoefficient(6, 3));
        assertEquals(120L, MathUtils.binomialCoefficient(10, 3));
    }

    @Test
    public void testBinomialCoefficient_LargeValues() {
        // Testing values that rely on the binomialCoefficientDouble path
        // (60 choose 30) is a large number
        assertEquals(118264581564861424L, MathUtils.binomialCoefficient(60, 30));
    }

    @Test(expected = IllegalArgumentException.class)
    public void testBinomialCoefficient_NLessThanK() {
        // n < k
        MathUtils.binomialCoefficient(5, 6);
    }

    @Test(expected = IllegalArgumentException.class)
    public void testBinomialCoefficient_NNegative() {
        // n < 0
        MathUtils.binomialCoefficient(-1, 0);
    }

    @Test(expected = ArithmeticException.class)
    public void testBinomialCoefficient_Overflow() {
        // A case where the result is extremely large. 
        // Note: The implementation uses binomialCoefficientDouble and checks for Long.MAX_VALUE.
        // Since we cannot easily predict the exact double precision behavior without running,
        // we target a value that would exceed Long.MAX_VALUE.
        // (1000 choose 500) is massive.
        MathUtils.binomialCoefficient(1000, 500);
    }

    /**
     * Note: The provided source code contains a logic branch:
     * if (result == Long.MAX_VALUE) throw ArithmeticException.
     * Since binomialCoefficientDouble returns a double, reaching exactly Long.MAX_VALUE 
     * as a rounded long is statistically rare but possible in certain edge cases of precision.
     */
}
